mapper.select:
select id, mix_area, param_code, param_name, param_value, regular_expression, error_tips, remark, del_flag, create_by, create_time, update_by, update_time from t_lhfl_schedule_params where del_flag = '0' and mix_area = #{mixArea} and INSTR(param_code, #{paramCode}) > 0 and INSTR(param_name, #{paramName}) > 0
order by mix_area
order by ${orderStr}
